@media (prefers-color-scheme: light) {
  :root {
    color-scheme: light;
    --primary-color: #8839ef;
    --primary-color-subtle: #9651f1;
    --body-background-color: #e6e9ef;
    --section-background-color: #eff1f5;
    --text-color: #4c4f69;
    --text-color-subtle: #5c5f77;
    --text-color-inverse: #dce0e8;
    --link-color: #1e66f5;
    --link-color-subtle: var(--text-color);
    --link-color-hover: #3677f6;
    --line-color-subtle: #bcc0cc;
    --button-text-color: var(--text-color);
    --button-text-color-hover: var(--text-color);
    --button-border-color: #ccd0da;
    --button-border-color-hover: #ccd0da;
    --button-background-color: #ccd0da;
    --button-background-color-hover: #bcc0cc;
    --input-text-color: var(--text-color);
    --input-text-color-hover: var(--text-color);
    --input-border-color: #ccd0da;
    --input-border-color-hover: #ccd0da;
    --input-background-color: #e6e9ef;
    --input-background-color-hover: #e6e9ef;
    --footer-text-color: var(--text-color-subtle);
  }
  :root ::selection {
    background-color: rgba(136, 57, 239, 0.3);
  }
  :root input::placeholder,
  :root textarea::placeholder {
    color: #6c6f85 !important;
  }
  :root .kx-item details summary .info img,
  :root .kx-item details .subsection > img {
    filter: brightness(0) saturate(100%) invert(43%) sepia(43%) saturate(515%) hue-rotate(196deg) brightness(49%) contrast(68%);
  }
  :root kx-claim,
  :root kx-key {
    --loader-color: #5c5f77;
    --success-color: #40a02b;
    --failure-color: #d20f39;
    --background-color: #ccd0da;
    --header-background-color: #bcc0cc;
  }
  :root a.button.button--donate.button--opencollective {
    background-color: #1e66f5;
    color: #dce0e8;
  }
  :root a.button.button--donate.button--opencollective:hover {
    background-color: #3677f6;
  }
  :root a.button.button--donate.button--opencollective svg {
    fill: #dce0e8;
  }
}
@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --primary-color: #cba6f7;
    --primary-color-subtle: #d9bdf9;
    --body-background-color: #181825;
    --section-background-color: #1e1e2e;
    --text-color: #cdd6f4;
    --text-color-subtle: #bac2de;
    --text-color-inverse: #11111b;
    --link-color: #89b4fa;
    --link-color-subtle: var(--text-color);
    --link-color-hover: #a1c4fb;
    --line-color-subtle: #45475a;
    --button-text-color: var(--text-color);
    --button-text-color-hover: var(--text-color);
    --button-border-color: #313244;
    --button-border-color-hover: #313244;
    --button-background-color: #313244;
    --button-background-color-hover: #45475a;
    --input-text-color: var(--text-color);
    --input-text-color-hover: var(--text-color);
    --input-border-color: #313244;
    --input-border-color-hover: #313244;
    --input-background-color: #181825;
    --input-background-color-hover: #181825;
    --footer-text-color: var(--text-color-subtle);
  }
  :root ::selection {
    background-color: rgba(203, 166, 247, 0.3);
  }
  :root input::placeholder,
  :root textarea::placeholder {
    color: #a6adc8 !important;
  }
  :root .kx-item details summary .info img,
  :root .kx-item details .subsection > img {
    filter: brightness(0) saturate(100%) invert(75%) sepia(82%) saturate(1008%) hue-rotate(189deg) brightness(120%) contrast(90%);
  }
  :root kx-claim,
  :root kx-key {
    --loader-color: #bac2de;
    --success-color: #a6e3a1;
    --failure-color: #f38ba8;
    --background-color: #313244;
    --header-background-color: #45475a;
  }
  :root a.button.button--donate.button--opencollective {
    background-color: #89b4fa;
    color: #11111b;
  }
  :root a.button.button--donate.button--opencollective:hover {
    background-color: #a1c4fb;
  }
  :root a.button.button--donate.button--opencollective svg {
    fill: #11111b;
  }
}
